//! Text templates for every generated file. Pure functions, unit-tested.
use crate::config::Config;
use crate::util::fill;

const DNSMASQ: &str = "\
# generated by pxe-installer - do not edit by hand
# --- listen only on the PXE NIC ---
interface=@IFACE@
bind-interfaces

# --- DHCP ---
dhcp-range=@DHCP_START@,@DHCP_END@,@NETMASK@,@LEASE@
dhcp-option=option:router,@SERVER_IP@
dhcp-option=option:dns-server,@SERVER_IP@
dhcp-authoritative

# --- static MAC->IP bindings: dhcp-host=mac,ip[,name] lines (pxe-ctl bind restarts dnsmasq) ---
conf-file=@HOSTS_FILE@
@ONLY_KNOWN@
# --- DNS (forward to upstream) ---
server=@UPSTREAM_DNS@
domain-needed
bogus-priv

# --- TFTP ---
enable-tftp
tftp-root=@TFTP_ROOT@

# --- UEFI PXE: client arch (option 93): 7 = x64 UEFI, 9 = x64 UEFI (EBC) ---
dhcp-match=set:efi64,option:client-arch,7
dhcp-match=set:efi64,option:client-arch,9
dhcp-boot=tag:efi64,bootx64.efi,@SERVER_IP@,@SERVER_IP@
# Legacy BIOS clients are intentionally not served.

log-dhcp
";

const GRUB: &str = r#"set timeout=5
set default=0

# Already installed? -> leave grub; UEFI firmware continues with the next boot entry (local disk).
if [ -f /done/${net_default_mac} ]; then
    echo "Host ${net_default_mac} is already installed - booting from local disk."
    sleep 2
    exit
fi

menuentry "Autoinstall Ubuntu 25.04 (WIPES THE DISK)" {
    echo "Loading kernel..."
    linux /casper/vmlinuz ip=dhcp url=http://@SERVER_IP@/iso/@ISO_NAME@ autoinstall "ds=nocloud-net\;s=http://@SERVER_IP@/autoinstall/" ---
    initrd /casper/initrd
}
menuentry "Boot from local disk" {
    exit
}
"#;

const USER_DATA: &str = r#"#cloud-config
autoinstall:
  version: 1
  locale: en_US.UTF-8
  keyboard: {layout: us}
  identity:
    hostname: @TARGET_HOSTNAME@
    username: @TARGET_USER@
    password: '@PW_HASH@'
  ssh:
    install-server: true
    allow-pw: true
  storage:
    layout:
      name: direct
  # Last step before reboot: tell the PXE server this MAC is done.
  late-commands:
    - |
      IF=$(ip route show default | awk '{print $5; exit}')
      MAC=$(cat /sys/class/net/$IF/address)
      curl -fsS --retry 5 --retry-delay 2 "http://@SERVER_IP@/cgi-bin/pxe-done?mac=$MAC"
"#;

const NETPLAN: &str = "\
network:
  version: 2
  ethernets:
    @IFACE@:
      dhcp4: false
      addresses: [@SERVER_IP@/@PREFIX@]
";

const APACHE_CONF: &str = "\
<Location \"/cgi-bin/pxe-done\">
    Require ip @NETWORK@/@PREFIX@
</Location>
";

pub const SELF_PATH: &str = "/usr/local/sbin/pxe-installer";
pub const CTL_WRAPPER_PATH: &str = "/usr/local/sbin/pxe-ctl";
pub const CGI_PATH: &str = "/usr/lib/cgi-bin/pxe-done";

pub fn dnsmasq_conf(c: &Config) -> String {
    let only_known = if c.only_known_hosts { "dhcp-ignore=tag:!known\n" } else { "" };
    fill(
        DNSMASQ,
        &[
            ("IFACE", c.iface.as_str()),
            ("DHCP_START", c.dhcp_start.as_str()),
            ("DHCP_END", c.dhcp_end.as_str()),
            ("NETMASK", c.netmask().to_string().as_str()),
            ("LEASE", c.lease.as_str()),
            ("SERVER_IP", c.server_ip.as_str()),
            ("HOSTS_FILE", c.hosts_file.as_str()),
            ("ONLY_KNOWN", only_known),
            ("UPSTREAM_DNS", c.upstream_dns.as_str()),
            ("TFTP_ROOT", c.tftp_root.as_str()),
        ],
    )
}

pub fn grub_cfg(c: &Config) -> String {
    fill(GRUB, &[("SERVER_IP", c.server_ip.as_str()), ("ISO_NAME", c.iso_name.as_str())])
}

pub fn user_data(c: &Config, pw_hash: &str) -> String {
    fill(
        USER_DATA,
        &[
            ("TARGET_HOSTNAME", c.target_hostname.as_str()),
            ("TARGET_USER", c.target_user.as_str()),
            ("PW_HASH", pw_hash),
            ("SERVER_IP", c.server_ip.as_str()),
        ],
    )
}

pub fn netplan(c: &Config) -> String {
    fill(
        NETPLAN,
        &[("IFACE", c.iface.as_str()), ("SERVER_IP", c.server_ip.as_str()), ("PREFIX", c.prefix.to_string().as_str())],
    )
}

pub fn apache_conf(c: &Config) -> String {
    let net = c.network().map(|n| n.to_string()).unwrap_or_default();
    fill(APACHE_CONF, &[("NETWORK", net.as_str()), ("PREFIX", c.prefix.to_string().as_str())])
}

/// Tiny CGI shim: Apache runs it as www-data, it re-enters this binary.
pub fn cgi_wrapper() -> String {
    format!("#!/bin/sh\nexec {SELF_PATH} cgi-done\n")
}

pub fn ctl_wrapper() -> String {
    format!("#!/bin/sh\nexec {SELF_PATH} ctl \"$@\"\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg() -> Config {
        Config { target_password: "longenough1".into(), ..Config::default() }
    }

    #[test]
    fn dnsmasq_has_uefi_and_hostsfile() {
        let s = dnsmasq_conf(&cfg());
        assert!(s.contains("dhcp-range=192.168.5.100,192.168.5.200,255.255.255.0,24h"));
        assert!(s.contains("dhcp-boot=tag:efi64,bootx64.efi,192.168.5.1,192.168.5.1"));
        assert!(s.contains("conf-file=/etc/dnsmasq.d/pxe-hosts.conf"));
        assert!(!s.contains("dhcp-ignore"));
        assert!(!s.contains('@'));
    }

    #[test]
    fn only_known_adds_ignore() {
        let mut c = cfg();
        c.only_known_hosts = true;
        assert!(dnsmasq_conf(&c).contains("dhcp-ignore=tag:!known"));
    }

    #[test]
    fn grub_guard_and_urls() {
        let s = grub_cfg(&cfg());
        assert!(s.contains("/done/${net_default_mac}"));
        assert!(s.contains("url=http://192.168.5.1/iso/ubuntu-25.04-beta-live-server-amd64.iso"));
        assert!(s.contains("nocloud-net\\;s=http://192.168.5.1/autoinstall/"));
        assert!(!s.contains('@'));
    }

    #[test]
    fn user_data_callback() {
        let s = user_data(&cfg(), "$6$salt$hash");
        assert!(s.contains("password: '$6$salt$hash'"));
        assert!(s.contains("http://192.168.5.1/cgi-bin/pxe-done?mac=$MAC"));
        assert!(!s.contains('@'));
    }

    #[test]
    fn apache_network() {
        assert!(apache_conf(&cfg()).contains("Require ip 192.168.5.0/24"));
    }
}
